const SCOPE = new URL(self.registration.scope);
const PREFIX = 'vatican-offline-' + encodeURIComponent(SCOPE.pathname) + '-';
const CACHE_NAME = PREFIX + PRECACHE.version;
const COMPLETE_URL = new URL('./__offline_complete__', SCOPE).href;
const INDEX_URL = new URL('./index.html', SCOPE).href;
const FILES = PRECACHE.files.map((file) => ({...file, absolute: new URL(file.url, SCOPE).href}));
const KNOWN = new Set(FILES.map((file) => file.absolute));

async function broadcast(message) {
  const clients = await self.clients.matchAll({type: 'window', includeUncontrolled: true});
  for (const client of clients) {
    if (client.url.startsWith(SCOPE.href)) client.postMessage(message);
  }
}

async function cacheStatus() {
  if (!(await caches.keys()).includes(CACHE_NAME)) {
    return {type: 'CACHE_STATUS', version: PRECACHE.version, ready: false, completed: 0, total: FILES.length, bytes: PRECACHE.bytes};
  }
  const cache = await caches.open(CACHE_NAME);
  const keys = new Set((await cache.keys()).map((request) => request.url));
  const completed = FILES.filter((file) => keys.has(file.absolute)).length;
  return {type: 'CACHE_STATUS', version: PRECACHE.version, ready: completed === FILES.length && keys.has(COMPLETE_URL),
    completed, total: FILES.length, bytes: PRECACHE.bytes};
}

async function download(file, cache) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 45000);
  try {
    const response = await fetch(file.absolute, {cache: 'reload', credentials: 'same-origin', redirect: 'error', signal: controller.signal});
    if (!response.ok || response.type === 'opaque') throw new Error('download ' + response.status + ': ' + file.url);
    const bytes = await response.clone().arrayBuffer();
    const digest = await crypto.subtle.digest('SHA-256', bytes);
    const sha256 = Array.from(new Uint8Array(digest), (value) => value.toString(16).padStart(2, '0')).join('');
    if (bytes.byteLength !== file.bytes || sha256 !== file.sha256) throw new Error('integrity check failed: ' + file.url);
    await cache.put(file.absolute, response);
  } finally {
    clearTimeout(timer);
  }
}

async function installCompleteCopy(repair = false) {
  const cache = await caches.open(CACHE_NAME);
  await cache.delete(COMPLETE_URL);
  const present = repair ? new Set((await cache.keys()).map((request) => request.url)) : new Set();
  const pending = FILES.filter((file) => !present.has(file.absolute));
  let next = 0;
  let completed = FILES.length - pending.length;
  let downloadedBytes = FILES.filter((file) => present.has(file.absolute)).reduce((total, file) => total + file.bytes, 0);
  let failure = null;
  const workers = Array.from({length: 4}, async () => {
    while (!failure && next < pending.length) {
      const file = pending[next++];
      try {
        await download(file, cache);
        completed++;
        downloadedBytes += file.bytes;
        await broadcast({type: 'CACHE_PROGRESS', version: PRECACHE.version, completed, total: FILES.length,
          downloadedBytes, bytes: PRECACHE.bytes});
      } catch (error) {
        failure ||= error;
      }
    }
  });
  await Promise.all(workers);
  if (failure) {
    if (!repair) await caches.delete(CACHE_NAME);
    await broadcast({type: 'CACHE_ERROR', version: PRECACHE.version, message: failure.message});
    throw failure;
  }
  await cache.put(COMPLETE_URL, new Response(JSON.stringify({version: PRECACHE.version, completed}), {
    headers: {'Content-Type': 'application/json'}
  }));
}

self.addEventListener('install', (event) => {
  // Do not skipWaiting here: a running older version keeps its matching cache until the user updates.
  event.waitUntil(installCompleteCopy());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const status = await cacheStatus();
    if (!status.ready) throw new Error('Cannot activate an incomplete offline copy');
    for (const name of await caches.keys()) {
      if (name.startsWith(PREFIX) && name !== CACHE_NAME) await caches.delete(name);
    }
    await self.clients.claim();
    await broadcast(status);
  })());
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'OFFLINE_STATUS') {
    event.waitUntil((async () => {
      const status = await cacheStatus();
      if (event.ports?.[0]) event.ports[0].postMessage(status);
      else event.source?.postMessage(status);
    })());
  }
  if (event.data?.type === 'ACTIVATE_UPDATE') event.waitUntil(self.skipWaiting());
  if (event.data?.type === 'REPAIR_OFFLINE') {
    repairInProgress ||= installCompleteCopy(true)
      .then(async () => broadcast(await cacheStatus()))
      .catch(() => {}) // installCompleteCopy already broadcasts an actionable error.
      .finally(() => { repairInProgress = null; });
    event.waitUntil(repairInProgress);
  }
});

let repairInProgress = null;

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== SCOPE.origin || !url.pathname.startsWith(SCOPE.pathname)) return;
  const canonical = url.origin + url.pathname;
  if (request.mode === 'navigate') {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE_NAME);
      const index = await cache.match(INDEX_URL);
      if (index) return index;
      return fetch(request);
    })());
    return;
  }
  if (!KNOWN.has(canonical)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);
    return (await cache.match(canonical)) || fetch(request);
  })());
});
